(159, 'Susu Ultra Coklat 200ml', 'Susu UHT', 'Membantu memelihara kondisi tubuh karena susu merupakan salah satu sumber protein alami, serta sebagai sumber vitamin alami, antara lain vitamin A, vitamin B1, B2, B3, B5, B6, B12, Vitamin C dan vitamin E. Susu juga merupakan sumber kalsium alami yang mudah diserap tubuh dan penting untuk pembentukan tulang dan gigi.', 'Dos isi 200 ml', 6000, '6.000-8.000', 24, 'Diminum langsung dingin/hangat', 'Sesuai kebutuhan', NULL, NULL, NULL, 'Lemak total, Lemak jenuh, Kolesterol, Protein, Karbohidrat total, Gula, Natrium, Kalium, Vitamin A, Vitamin, Vitamin D3, Vitamin E, Vitamin K, Vitamin B1, Vitamin B2, Vitamin B3, Vitamin B6, Vitamin B12, Asam Folat, Kalsium, Zat Besi, Iodium, Zink, Magnesium, Fosfor, Selenium', 'Alergi susu', 'https://www.ultrajaya.co.id/product/ultra-milk', 0, '2026-05-15 06:00:47', '2026-05-15 06:00:47'),
(160, 'Susu Ultra Stroberi 125ml', 'Susu UHT', 'Membantu memelihara kondisi tubuh karena susu merupakan salah satu sumber protein alami, serta sebagai sumber vitamin alami, antara lain vitamin A, vitamin B1, B2, B3, B5, B6, B12, Vitamin C dan vitamin E. Susu juga merupakan sumber kalsium alami yang mudah diserap tubuh dan penting untuk pembentukan tulang dan gigi.', 'Dos isi 125 ml', 3000, '3.000-5.000', 50, 'Diminum langsung dingin/hangat', 'Sesuai kebutuhan', NULL, NULL, NULL, 'Lemak total, Lemak jenuh, Kolesterol, Protein, Karbohidrat total, Gula, Natrium, Kalium, Vitamin A, Vitamin, Vitamin D3, Vitamin E, Vitamin K, Vitamin B1, Vitamin B2, Vitamin B3, Vitamin B6, Vitamin B12, Asam Folat, Kalsium, Zat Besi, Iodium, Zink, Magnesium, Fosfor, Selenium', 'Alergi susu', 'https://www.ultrajaya.co.id/product/ultra-milk', 0, '2026-05-15 06:00:47', '2026-05-15 06:00:47'),
(161, 'Susu Ultra Coklat 250ml', 'Susu UHT', 'Membantu memelihara kondisi tubuh karena susu merupakan salah satu sumber protein alami, serta sebagai sumber vitamin alami, antara lain vitamin A, vitamin B1, B2, B3, B5, B6, B12, Vitamin C dan vitamin E. Susu juga merupakan sumber kalsium alami yang mudah diserap tubuh dan penting untuk pembentukan tulang dan gigi.', 'Dos isi 250ml', 7000, '7.000-9.000', 64, 'Diminum langsung dingin/hangat', 'Sesuai kebutuhan', NULL, NULL, NULL, 'Lemak total, Lemak jenuh, Kolesterol, Protein, Karbohidrat total, Gula, Natrium, Kalium, Vitamin A, Vitamin, Vitamin D3, Vitamin E, Vitamin K, Vitamin B1, Vitamin B2, Vitamin B3, Vitamin B6, Vitamin B12, Asam Folat, Kalsium, Zat Besi, Iodium, Zink, Magnesium, Fosfor, Selenium', 'Alergi susu', 'https://www.ultrajaya.co.id/product/ultra-milk', 0, '2026-05-15 06:00:47', '2026-05-15 06:00:47'),
(162, 'SUSU ULTRA STROBERI 250ML', 'Susu UHT', 'Membantu memelihara kondisi tubuh karena susu merupakan salah satu sumber protein alami, serta sebagai sumber vitamin alami, antara lain vitamin A, vitamin B1, B2, B3, B5, B6, B12, Vitamin C dan vitamin E. Susu juga merupakan sumber kalsium alami yang mudah diserap tubuh dan penting untuk pembentukan tulang dan gigi.', 'Dos isi 250ml', 7000, '7.000-9.000', 24, 'Diminum langsung dingin/hangat', 'Sesuai kebutuhan', NULL, NULL, NULL, 'Lemak total, Lemak jenuh, Kolesterol, Protein, Karbohidrat total, Gula, Natrium, Kalium, Vitamin A, Vitamin, Vitamin D3, Vitamin E, Vitamin K, Vitamin B1, Vitamin B2, Vitamin B3, Vitamin B6, Vitamin B12, Asam Folat, Kalsium, Zat Besi, Iodium, Zink, Magnesium, Fosfor, Selenium', 'Alergi susu', 'https://www.ultrajaya.co.id/product/ultra-milk', 0, '2026-05-15 06:00:47', '2026-05-15 06:00:47');

