--
-- Trigger `order_items`
--
DELIMITER $$
CREATE TRIGGER `tr_reduce_stock` AFTER INSERT ON `order_items` FOR EACH ROW BEGIN
                UPDATE medicines SET stock = stock - NEW.quantity 
                WHERE id = NEW.medicine_id;
            END
$$
DELIMITER ;

