--
-- Struktur untuk view `vw_sales_summary`
--
DROP TABLE IF EXISTS `vw_sales_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_sales_summary`  AS SELECT `m`.`id` AS `medicine_id`, `m`.`name` AS `medicine_name`, sum(`oi`.`quantity`) AS `total_sold`, sum(`oi`.`subtotal`) AS `total_revenue` FROM (`order_items` `oi` join `medicines` `m` on(`oi`.`medicine_id` = `m`.`id`)) GROUP BY `m`.`id`, `m`.`name` ;

